From d66b44501603bd1d51e9a9df5c4d8791360c1652 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 09:23:47 +0100
Subject: [PATCH] ExpandableListItem: highlight partially visible items on
 hover

Hovering an item that was partly scrolled out of view didn't highlight
it, because changing currentIndex would make the view scroll to it. Now
contentY is set back afterwards, which keeps the view where it was.

BUG: 512397
---
 .../plasmaextracomponents/qml/ExpandableListItem.qml | 12 +++++++++---
 1 file changed, 9 insertions(+), 3 deletions(-)

diff --git a/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml b/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
index 168c4f6f5..42be9bec5 100644
--- a/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
+++ b/src/declarativeimports/plasmaextracomponents/qml/ExpandableListItem.qml
@@ -427,12 +427,18 @@ Item {

         // using onPositionChanged instead of onContainsMouseChanged so this doesn't trigger when the list reflows
         onPositionChanged: {
-            // don't change currentIndex if it would make listview scroll
+            // changing currentIndex makes listview scroll to show the whole item
             // see https://bugs.kde.org/show_bug.cgi?id=387797
             // this is a workaround till https://bugreports.qt.io/browse/QTBUG-114574 gets fixed
             // which would allow a proper solution
-            if (parent.y - listItem.ListView.view.contentY >= 0 && parent.y - listItem.ListView.view.contentY + parent.height  + 1 /* border */ < listItem.ListView.view.height) {
-                listItem.ListView.view.currentIndex = (containsMouse ? listItem.index : -1)
+            const view = listItem.ListView.view;
+            if (parent.y - view.contentY >= 0 && parent.y - view.contentY + parent.height  + 1 /* border */ < view.height) {
+                view.currentIndex = (containsMouse ? listItem.index : -1)
+            } else if (!view.moving) {
+                // setting contentY back makes the view stop following the current item
+                const contentY = view.contentY;
+                view.currentIndex = (containsMouse ? listItem.index : -1);
+                view.contentY = contentY;
             }
         }
         onPressed: (mouse) => {
